```php
<?php

namespace App\Http\Controllers;

use Illuminate\Http\Request;
use App\Models\User;

class UserController extends Controller
{
    /**
     * Fetch a user by ID and return a magical JSON response.
     *
     * @param  int  $id
     * @return \Illuminate\Http\JsonResponse
     */
    public function getUserById($id)
    {
        // 🔮 Search the enchanted database for the user
        $user = User::find($id);

        if (!$user) {
            return response()->json([
                'error' => 'User not found',
                'message' => 'The user crystal could not be located in the realm of users.'
            ], 404);
        }

        // ✨ Enchant the user data into a magical JSON crystal
        $userCrystal = [
            'id' => $user->id,
            'name' => $user->name,
            'email' => $user->email,
            'created_at' => $user->created_at->diffForHumans(),
            'magic_power' => '✨ ' . ($user->id % 100) . '%',
            'message' => 'You have successfully summoned the user crystal!'
        ];

        return response()->json($userCrystal, 200);
    }
}
```

